const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // Define region: Wales and central/southern England
    const region = ee.Geometry.Polygon([
      [[-5.5, 49.9], [-5.5, 53.5], [2.0, 53.5], [2.0, 49.9], [-5.5, 49.9]]
    ]);

    // Get GPM IMERG Daily precipitation for January 2, 2024
    const date = '2024-01-02';
    const collection = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
      .filterDate(date, '2024-01-03')
      .filterBounds(region)
      .select('precipitation');

    const size = collection.size().getInfo();
    console.log(`Images found: ${size}`);

    if (size === 0) {
      console.log('No precipitation data available for this date');
      console.log('<answer>C1</answer>');
      return;
    }

    // Get the image (GPM provides half-hourly, sum to daily)
    const dailyPrecip = collection.sum();

    // Check pixel count
    const countResult = dailyPrecip.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 10000,
      maxPixels: 1e9
    }).getInfo();

    const pixelCount = countResult.precipitation || 0;
    console.log(`Valid pixels: ${pixelCount}`);

    if (pixelCount === 0) {
      console.log('No valid pixels in region');
      console.log('<answer>C2</answer>');
      return;
    }

    // Get statistics for the region
    const stats = dailyPrecip.reduceRegion({
      reducer: ee.Reducer.max().combine({
        reducer2: ee.Reducer.mean(),
        sharedInputs: true
      }),
      geometry: region,
      scale: 10000,
      maxPixels: 1e9
    }).getInfo();

    const maxPrecip = stats.precipitation_max;
    const meanPrecip = stats.precipitation_mean;

    console.log(`Max precipitation: ${maxPrecip ? maxPrecip.toFixed(2) : 'null'} mm`);
    console.log(`Mean precipitation: ${meanPrecip ? meanPrecip.toFixed(2) : 'null'} mm`);

    if (maxPrecip === null || maxPrecip === undefined || isNaN(maxPrecip)) {
      console.log('Calculation failed - invalid result');
      console.log('<answer>C3</answer>');
      return;
    }

    // Check if any area received >= 35mm
    if (maxPrecip >= 35.0) {
      console.log('At least one area received >= 35mm of rain');
      console.log('<answer>A</answer>');
    } else {
      console.log('No areas received >= 35mm of rain');
      console.log('<answer>B</answer>');
    }

  } catch (error) {
    console.log(`Error: ${error.message}`);
    console.log('<answer>D</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
